async () => {
  const { execSync } = require('child_process');
  const hosts = ['google.com', 'cloudflare.com', 'github.com'];
  const results = {};

  for (const host of hosts) {
    try {
      // Using -c 1 to send only one packet for quick testing
      const output = execSync(`ping -c 1 ${host}`, { encoding: 'utf-8', timeout: 5000 });
      results[host] = { reachable: true, output };
    } catch (error) {
      results[host] = { reachable: false, error: error.message };
    }
  }

  return results;
}

